"""Seal the memory decision from completed measurements and exact checks."""
import json,subprocess
from pathlib import Path
from sdf_cfd_mesher_v4.common.authority import file_hash
from summarize_native_memory import ROOT,OUT,load,save

def run():
    m=load('BEFORE_AFTER.json');p=load('PHASE_SUMMARY.json');b=load('BOUNDED_SF2.json');g=load('GENERAL_REGRESSION.json')
    audit=load('fresh/FINAL_NATIVE_AUDIT.json');comparison=load('fresh/SCIENTIFIC_COMPARISON.json');start=load('START_AUTHORITY.json')
    assert all(x['passed'] and x['restart_exact'] for x in b) and g['passed']
    assert comparison['passed'] and comparison['remesh_events']==0
    prior=ROOT/'results/native_sf2_production_plumbing'
    assert all(file_hash(prior/name)==digest for name,digest in start['prior'].items())
    retained=[r for r in p['retained'] if r.get('mark')=='committed_layer']
    table='| Layer | Post-commit RSS (bytes) |\n|---:|---:|\n'+'\n'.join(f"| {r['layer']} | {r['rss']:,} |" for r in retained)
    peak=m['fresh_peak'];probe=m['matched_copy_probe'];tests=(OUT/'TESTS_FINAL.log').read_text().strip().splitlines()[-1]
    sections=[
    ('A. Authority verification',f"Starting HEAD: `{start['head']}`. The prior report and authority SHA-256 values match. Prior sealed evidence is unchanged. The native mixed-front runner remains production authority. Automatic remeshing remains enabled. V3, scientific gates, SDF geometry, schedules, correction algorithms, and certificate predicates were not changed."),
    ('B. Baseline memory reproduction','The historical aggregate full-run peak is 3,405,565,952 bytes. Bounded reproductions exercised fresh initialization/first commit, warning initialization, and complete layer-20 certification. The first-commit reproduction peaked at 1,263,632,384 bytes during future spot checks. The isolated certificate reproduction peaked at 1,552,711,680 bytes, including eight exact-worker processes. Isolated warning initialization peaked at 885,620,736 bytes. These are distinct workloads, not substitute full-build baselines. The prior run recorded cumulative parent high-water values, not a full time-resolved allocation trace. It also included a numerical-runtime repair; the complete historical difference cannot be attributed solely to these patches.'),
    ('C. Phase-by-phase RSS',f"The fresh run sampled the production parent and child processes every 0.05 s. Phase wrappers cover projection, atlas, detailed lookahead, exact Jacobians, future checks, immediate certification, evidence I/O, checkpointing, and final validation/audit. Largest observed aggregate peak RSS was {m['optimized_peak_rss']:,} bytes. The internal trace peak was {peak['rss']:,} bytes at {peak['seconds']:.3f} s, layer {peak['layer']}, phase `{peak['phase']}`. See PHASE_SUMMARY.json and the full RSS_TRACE.json. Shared pages may be counted in more than one process; this matches the historical aggregate-RSS convention."),
    ('D. Allocation-class breakdown','ALLOCATION_AUDIT.json records measured reachable Python/container bytes and unique NumPy backing-buffer bytes. Views are deduplicated. These values are not summed as a disjoint RSS partition. Baseline complete certificate geometry owns 408,199,680 bytes. Initial projection outputs own 188,161,620 bytes. A measured active detailed-lookahead input graph contained 165,086,240 Python/container bytes and 81,040,136 array bytes. The native state uses mapped geometry and disk-backed receipt tables. Native library heaps and worker runtimes are measured by RSS, not invented per-object estimates.'),
    ('E. Reference/lifetime audit','One native backing owns committed prism coordinates and connectivity. Entity views share it, including transaction copies. Atlas coordinates share the native forecast backing on restart. Planner proposal buffers are private and bounded. Provider history retains scalar timings and validation identities, not old numerical result arrays. Ordinary SF2 has no remesh journal snapshots. Scope release after the bounded baseline reduced RSS from the active proposal/cache footprint to 323,923,968 bytes. Explicit diagnostic SDF memo clearing and GC did not produce a comparable reduction; no forced-GC loop was added to production.'),
    ('F. NumPy copy audit','Removed whole-array tobytes hashing. Replaced concatenate plus four whole-shell fancy-index buffers and stack in certificate geometry construction with one output allocation filled by layer and edge plane. Labels are written directly into their existing uint64 output type. No floating-point arithmetic or precision changed. Remaining copies include private candidate trajectories, local support slices, transaction pair conversion, and bounded mapped-block audit arithmetic. No narrower scientific dtype was introduced.'),
    ('G. Forecast memory','The initial projection returned 188,161,620 bytes of arrays. Production subsequently consumes only coordinates and normals, totaling 51,026,880 bytes. The other 137,134,740 bytes are now released immediately after persistence, before twenty metric scans. All retained arrays are the original buffers, not copies. Current native forecasts remain mapped. Past coordinates remain available because complete prefix identity and restart validation use them; they are not expanded into per-state Python histories.'),
    ('H. Atlas memory','The native atlas borrows authoritative mapped forecast geometry. A focused shares-memory test enforces this. Masks, source identities, warnings, and bounded active supports remain. Accepted planner output still uses the existing private-buffer ownership contract. No atlas algorithms, activation rules, or region IDs changed. The layer 1/5/11/12/20 native atlas identities match preserved evidence exactly.'),
    ('I. Detailed-lookahead memory','Measured local detailed inputs and outputs are in ALLOCATION_AUDIT.json. The largest measured input includes retained local metric/planner records; this is not a dense global reconstruction operator. SideIndex scans source-edge AABBs and constructs exact geometry only for the qualified bounded candidate scope. Existing locality limits and correction search order remain unchanged.'),
    ('J. Reconstruction/Jacobian cache memory','The bounded active probe retained 7,054 exact-Jacobian entries, with 4,606 hits and 7,054 misses. Measured reachable receipt storage was 6,020,275 bytes. Parent CAD algebra caches were empty in that probe. Existing planner passive-state eviction clears detailed metrics, spatial rows, selections, and proof caches. A weak-reference test now proves release of those buffers. No arbitrary new eviction threshold was introduced.'),
    ('K. Certificate working-set memory','The persistent manifest remains mapped and compact. The transient certificate owns quad/label outputs, one layer-owned pair population, screening arrays, and exact fallback worker jobs. It does not expand all 56,462,864 relations into Python objects. The optimized geometry and labels have exactly the same hashes as the frozen allocation-layout reference. Full-run certificate populations and outcomes are checked against the qualified shell. The adapter source identity changes because its storage implementation changes; mathematical kernel sources remain unchanged. The optimized complete isolated certificate still peaks near 1.556 GB versus 1.553 GB before: worker/native-kernel work now determines that ceiling, so the 310 MB construction-probe saving is not claimed as an equal reduction of the entire certificate peak. Measured proof inputs own 430,328,208 bytes (quad/label outputs plus 22,128,528 bytes of packed pairs). Proof outputs own 8,298,198 array bytes and 29,649,132 measured Python/container bytes. At the fresh full-run peak, the parent holds 1,494,192,128 bytes RSS and eight workers hold 770,195,456 bytes in total. The native manifest index measures 122,929 Python/container bytes over 643,391,351 disk bytes.'),
    ('L. Checkpoint memory','Native checkpoint components already stream to content-addressed files. Geometry views do not materialize cell dictionaries. SQLite receipt publication iterates rows. This path was retained and measured, not replaced. Scientific report I/O now streams canonical JSON tokens to gzip and SHA-256, avoiding a simultaneous plain-object graph, complete string, and complete bytes payload. Byte-equality and round-trip tests cover the original format.'),
    ('M. Transaction-journal memory','SF2 performed zero topology-changing transactions. Native immutable prism views share backing arrays across ordinary copies. The bounded general-SDF regression exercised the real journal and removed 47 previously committed cells. Automatic remeshing was not disabled to reduce memory.'),
    ('N. Reporting/debug retention','The production event collector stores scalar phase timings and hashes. The profiler stores RSS samples and allocation summaries; it does not retain inspected arrays. Detailed allocation traversal is disabled in the full timed run to avoid profiling object-graph traversal as production work. Full-run RSS sampling remains enabled, and its cost is included in runtime and RSS. Large raw evidence is sealed with verified hashes rather than discarded.'),
    ('O. Dominant root causes','Measured avoidable sources were full certificate construction/hash copies and cold projection fields retained through initial validation. Whole-array hashing also affected many storage and scientific-identity call sites. Local detailed and exact-worker working sets remain real bounded execution costs. The compact manifest index and native checkpoint restart are not the source of the historical multi-gigabyte transient peak. Historical cumulative maxima cannot identify every allocation at the old aggregate peak; matched probes isolate the changes that can be attributed directly.'),
    ('P. Memory fixes','1. Hash contiguous NumPy buffers directly.\n2. Fill certificate geometry/labels by layer into one output owner.\n3. Release unused initial projection fields after persistence.\n4. Stream canonical report encoding and hashing.\n5. Add observational production phase/RSS instrumentation and lifetime regressions.\n\nNo scientific algorithm, gate, dtype, trigger, remesh template, or default production selection changed.'),
    ('Q. Before/after memory comparison',f"Historical full peak: {m['baseline_peak_rss']:,} bytes. Fresh optimized peak: {m['optimized_peak_rss']:,} bytes. Reduction: {m['reduction_bytes']:,} bytes ({m['reduction_percent']:.2f}%). The controlled full-size geometry/hash probe fell from {probe['before']['peak']['rss']:,} to {probe['after']['peak']['rss']:,} bytes with identical hashes. The hash-only intermediate result was {probe['hash_only']['peak']['rss']:,} bytes. This matched probe separates code allocation savings from historical runtime/allocator differences."),
    ('R. Runtime comparison',f"Fresh scientific execution: {m['scientific_seconds']:.3f} s, within the 1,800 s cap. Difference from 1,393.28 s native baseline: {m['native_runtime_difference']:+.3f} s. Difference from 1,248.01 s legacy baseline: {m['legacy_runtime_difference']:+.3f} s. Runtime includes RSS sampling and mandatory final comparison. EVENT_TIMES.json separates preparation, numerical validation, certification, and state work. Historical runtime includes a runtime-repair pass; do not treat the whole difference as an isolated optimization speedup."),
    ('S. Layer-by-layer retained RSS',table+'\n\nPost-commit RSS includes mapped pages and allocator retention, not only live scientific arrays. PHASE_SUMMARY.json also records layer 0 and final validation. The transient peak and post-commit series must be read separately. Layers 12-20 plateau between 768,544,768 and 768,942,080 bytes, a 397,312-byte range. Early active-search RSS rises, then stops rising when active work ends. This is evidence against continued layer-by-layer retention in passive advancement; it is not a claim that every resident allocator page is a live scientific array.'),
    ('T. Bounded SF2 regression','All five native checkpoints (1, 5, 11, 12, 20) passed exact scientific identity, atlas, forecast, quality/certificate audit, and native restart. Remesh count remains zero. The layer-20 native audit covers all 56,462,864 relations with zero missing, duplicates, forbidden, or unresolved results. BOUNDED_SF2.json contains each result.'),
    ('U. General-SDF remesh regression',f"The live bounded native runner removed 45 layer-4 prisms and two layer-5 tetrahedra, committed the qualified remesh, and restarted exactly. Adjusted schedules, wall, and first layer remained exact. The existing acceptance path checked complete volume/certificate/interface gates and bounded neighbor continuation. This run stops after the remesh transaction; it does not claim a second fresh production layer-6 build. Runtime: {g['seconds']:.3f} s; peak RSS: {g['peak_rss']:,} bytes. GENERAL_REGRESSION.json and its rollback manifest preserve the records."),
    ('V. Fresh optimized SF2 run','Started from authoritative layer 0 through the native MixedFrontRunner. No accepted reference correction coordinates were construction inputs. Completed 20 layers and 2,126,040 prisms with zero termination/remesh events. All committed hard gates pass. The native runner remains the sole production authority, with automatic remesh enabled.'),
    ('W. Scientific equality',f"Coordinates, connectivity, correction decisions, hard metric arrays, conditioning arrays, and certificate pair/outcome populations match the qualified reference. Final required relations: {audit['certificate']['active']:,}; missing/duplicate/forbidden/unresolved: 0/0/0/0. Wall identity: `{audit['wall']}`. First-layer identity: `{audit['first_layer']}`. h1 remains 0.000166527069 m. Implementation-source bindings are not falsely required to equal the old storage implementation."),
    ('X. Determinism','Native checkpoint/forecast replay is exact for the five SF2 checkpoints and the real general-SDF remesh. Canonical scientific bytes remain exact under streamed encoding. Certificate geometry and label hashes reproduce the frozen allocation implementation. The fresh full SF2 shell matches preserved scientific evidence. No second full SF2 build was required.'),
    ('Y. Tests',tests+'\n\nA post-run profiling-tool cleanup first failed because its temporary imported checkpoint still had live mmap owners. The tool now releases those owners before temporary-directory cleanup; the complete probe rerun exits successfully. The failed log is preserved. This was not a production mesh failure.\n\nThe focused suite covers native persistence/providers, compact manifest lookup, mixed transactions, trigger policy, certificate adapter, atlas, streamed encoding, no-copy hashing, projection lifetime release, and passive cache release. Live bounded and full-run checks are recorded separately; historical test fixtures are not presented as fresh full-run evidence.'),
    ('Z. Classification',m['classification']+'. Dominant measured avoidable allocation waste was removed. The fresh production shell remains scientifically exact. The remaining working sets are bounded and phase-attributed. Historical high-water limitations and runtime differences are explicit.'),
    ('AA. Recommended next task','A. Full transition-to-core integration. Native production authority and automatic bounded remeshing remain enabled. No core work was implemented in this task. Git scope: V4 task files only; zero V3 task changes. All 155 unrelated dirty-status entries remain unchanged. COMMITTED_PATHS.json lists the complete task path set.')]
    report='## Decision question\n\nWhat causes the qualified native mixed-front SF2 runner to reach 3,405,565,952 bytes peak RSS, and can that memory be reduced without changing any scientific result?\n\n'
    report+='\n\n'.join('### '+title+'\n\n'+body for title,body in sections)+'\n'
    (OUT/'report.md').write_text(report,encoding='utf8',newline='\n')
    sources=[p for p in ROOT.rglob('*.py') if 'results' not in p.relative_to(ROOT).parts and p.name in {
        'authority.py','scientific_stream.py','production.py','task3c_io.py','task4_initial_scan.py','run_native_sf2.py','native_memory_observer.py','profile_native_first_commit.py','profile_native_copy_probe.py','profile_native_memory_baseline.py','qualify_native_memory.py','summarize_native_memory.py','seal_native_memory_report.py','verify_native_memory_completion.py','native_memory_artifacts.py','test_native_memory.py'}]
    evidence={p.relative_to(OUT).as_posix():file_hash(p) for p in OUT.rglob('*') if p.is_file() and p.name not in ('AUTHORITY.json','HASHES.json') and not any(x in p.parts for x in ('objects','build','checkpoints')) and p.suffix not in ('.npy','.npz')}
    save('AUTHORITY.json',dict(task='ProfileAndReduceV4NativeRunnerMemory',classification=m['classification'],starting_commit=start['head'],
        prior_authority=start['prior'],report_sha256=file_hash(OUT/'report.md'),source_sha256={p.relative_to(ROOT).as_posix():file_hash(p) for p in sources},
        evidence_sha256=evidence,production_authority='native-mixed-front',automatic_remesh=True,scientific_gates_changed=False,v3_task_changes=0))
    save('HASHES.json',dict(report=file_hash(OUT/'report.md'),authority=file_hash(OUT/'AUTHORITY.json')))
if __name__=='__main__':run()
